<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pastino Website Admin</title><link rel="stylesheet" href="../assets/style.css?v=1"></head><body><main class="adminWrap"><a class="back" href="../">← Website</a><div class="adminTitle"><div><div class="eyebrow dark">PASTINO CONTROL</div><h1>Website admin</h1></div></div><div class="adminLogin"><input id="password" type="password" placeholder="Admin password"><button id="unlock" class="primary">Unlock admin</button></div><div id="message"></div><div id="adminContent" class="hidden">
<section class="adminCard"><h2>Website settings</h2><div class="formGrid"><label>Brand<input id="brandName"></label><label>WhatsApp<input id="whatsappNumber" placeholder="961xxxxxxxx"></label><label>Currency<input id="currency"></label><label>Delivery fee<input id="deliveryFee" type="number" step="0.01"></label><label class="span2">Hero title<input id="heroTitle"></label><label class="span2">Hero subtitle<textarea id="heroSubtitle"></textarea></label></div><button id="saveSettings" class="primary">Save settings</button></section>
<section class="adminCard"><h2>Menu items</h2><div id="menuList" class="adminList"></div><h3 id="itemFormTitle">Add item</h3><input id="itemId" type="hidden"><div class="formGrid"><label>Name<input id="itemName"></label><label>Price<input id="itemPrice" type="number" step="0.01"></label><label class="span2">Description<input id="itemDescription"></label><label class="span2">Image URL<input id="itemImage"></label><label>Upload image<input id="itemUpload" type="file" accept="image/png,image/jpeg,image/webp"></label><label>Sort order<input id="itemSort" type="number"></label><label class="checkline"><input id="itemAvailable" type="checkbox" checked> Available</label><label class="checkline"><input id="itemCustomizable" type="checkbox" checked> Customizable</label></div><button id="saveItem" class="primary">Save menu item</button></section>
<section class="adminCard"><h2>Build options</h2><div id="optionList" class="adminList"></div><input id="optionId" type="hidden"><div class="formGrid"><label>Name<input id="optionName"></label><label>Type<select id="optionKind"><option value="pasta">pasta</option><option value="sauce">sauce</option><option value="topping">topping</option><option value="cheese">cheese</option></select></label><label>Emoji<input id="optionEmoji" value="✦"></label><label>Extra price<input id="optionPrice" type="number" step="0.01"></label><label>Sort order<input id="optionSort" type="number"></label><label class="checkline"><input id="optionAvailable" type="checkbox" checked> Available</label></div><button id="saveOption" class="primary">Save option</button></section>
</div></main><script src="admin.js?v=1"></script></body></html>
